const slots = $slots;
probe(Array.isArray(slots.members) && slots.members.length > 0, "the statement must describe at least one group");
probe(Number.isInteger(slots.threshold) && slots.threshold > 0, "the winning threshold must be a positive integer");
const total = slots.members.reduce((sum, member) => sum + member.seats, 0);
probe(total >= slots.threshold, "the stated groups must reach the winning threshold");
const chosen = slots.members.filter((member) => member.seats >= slots.threshold);
probe(chosen.length > 0, "at least one group must reach the winning threshold");
const losing = slots.members.filter((member) => member.seats > slots.threshold);
probe(losing.length === 1, "exactly one group must have more than the threshold, not " + losing.length);
const coalitions = [];
for (let start = 0; start < chosen.length; start += 1) {
  for (let end = start + 1; end < chosen.length; end += 1) {
    const subset = chosen.slice(start, end);
    if (subset.reduce((sum, member) => sum + member.seats, 0) < slots.threshold) {
      continue;
    }
    const names = subset.map((member) => member.name);
    if (names.length === 1) {
      coalitions.push(names[0] + " alone");
    } else {
      coalitions.push(names.slice(0, -1).join(", ") + " and " + names[ names.length - 1] + " together");
    }
  }
}
probe(coalitions.length > 0, "some coalition of chosen groups must reach the threshold");
return "The minimal winning coalitions are " + coalitions.join(", ") + ".";
